const output = $input.first().json.stdout;
const fileMatch = output.match(/^FILE:(.+)$/m);
const fileName = fileMatch ? fileMatch[1] : 'unknown';

const titleMatch = output.match(/^title:\s*(.+)$/m);
const title = titleMatch ? titleMatch[1].trim() : fileName.replace('.md', '');

const descMatch = output.match(/^description:\s*(.+)$/m);
const abstractMatch = output.match(/^>\s*(.+)$/m);
const description = descMatch ? descMatch[1].trim() : (abstractMatch ? abstractMatch[1].trim() : '无摘要');

const tagsMatch = output.match(/^tags:\s*\[(.+?)\]/m);
const tags = tagsMatch ? tagsMatch[1].replace(/"/g, '').trim() : '';

return [{
  json: {
    file: fileName,
    title: title,
    description: description.substring(0, 200),
    tags: tags,
    gitea_url: `$env.GITEA_URL/ai-area/hermes-wiki/raw/branch/main/entities/${fileName}`
  }
}];

